function Metric({ label, value, detail, icon: Icon, tone = 'teal' }: { label: string; value: string | number; detail: string; icon: typeof Users; tone?: 'teal' | 'orange' | 'red' | 'cream' }) {
  const colors = { teal: 'bg-[#dcefed] text-[#236d68]', orange: 'bg-[#fce6d4] text-[#a25528]', red: 'bg-[#fbe2de] text-[#a4382f]', cream: 'bg-[#f8edcc] text-[#8c651e]' };
  return <div className="surface lift rounded-2xl p-4 md:p-5"><div className="mb-4 flex items-start justify-between"><span className={`flex h-10 w-10 items-center justify-center rounded-xl ${colors[tone]}`}><Icon size={20} /></span><MoreHorizontal size={18} className="text-[hsl(var(--muted-foreground))]" /></div><p className="mono text-2xl font-bold tracking-[-.04em]">{value}</p><p className="mt-1 text-sm font-semibold">{label}</p><p className="mt-2 text-xs text-[hsl(var(--muted-foreground))]">{detail}</p></div>;
}

function SectionTitle({ title, detail, action }: { title: string; detail?: string; action?: ReactNode }) {
  return <div className="mb-4 flex flex-wrap items-end justify-between gap-3"><div><h2 className="text-base font-bold tracking-[-.02em]">{title}</h2>{detail && <p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{detail}</p>}</div>{action}</div>;
}

function PrimaryButton({ children, onClick, href, variant = 'primary', type = 'button', disabled = false, testId = 'button-action' }: { children: ReactNode; onClick?: () => void; href?: string; variant?: 'primary' | 'soft' | 'outline' | 'danger'; type?: 'button' | 'submit'; disabled?: boolean; testId?: string }) {
  const style = { primary: 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))] hover:brightness-110', soft: 'bg-[#dcefed] text-[#236d68] hover:bg-[#cde6e2]', outline: 'border border-[hsl(var(--border))] bg-[hsl(var(--card))] hover:border-[hsl(var(--primary))]', danger: 'bg-[#a4382f] text-white hover:brightness-110' }[variant];
  if (href) return <Link href={href} className={`focus-ring inline-flex min-h-11 items-center justify-center gap-2 rounded-xl px-4 text-sm font-bold transition ${style}`} data-testid={testId}>{children}</Link>;
  return <button type={type} disabled={disabled} onClick={onClick} className={`focus-ring inline-flex min-h-11 items-center justify-center gap-2 rounded-xl px-4 text-sm font-bold transition disabled:cursor-not-allowed disabled:opacity-50 ${style}`} data-testid={testId}>{children}</button>;
}

function StatusBadge({ status }: { status: Severity | null }) {
  const t = useCopy();
  if (status === 'green') return <Badge tone="green" icon={<CheckCircle2 size={13} />}>{t('home')}</Badge>;
  if (status === 'yellow') return <Badge tone="yellow" icon={<AlertCircle size={13} />}>{t('teleconsult')}</Badge>;
  if (status === 'red') return <Badge tone="red" icon={<AlertCircle size={13} />}>{t('emergency')}</Badge>;
  return <Badge>Not assessed</Badge>;
}

